package com.nattechnologies.trastcms.plugins.pay.cleanpay;
import org.springframework.stereotype.Component;import java.lang.reflect.*;import java.net.URI;import java.util.*;import java.util.concurrent.*;
@Component public class CleanPayGatewaySupport{private final CleanPayClient client;public CleanPayGatewaySupport(CleanPayClient c){client=c;}
public Object invoke(Class<?> contract,String method,Object[] args,Class<?> rawReturn){Map<String,Object> input=flatten(args);CleanPayClient.GatewayResponse response=client.charge(input);Type generic=Arrays.stream(contract.getMethods()).filter(x->x.getName().equals(method)&&x.getParameterCount()==args.length).findFirst().map(Method::getGenericReturnType).orElse(rawReturn);return adapt(generic,rawReturn,response);}
private Map<String,Object> flatten(Object[] args){Map<String,Object> out=new LinkedHashMap<>();if(args==null)return out;for(Object a:args)walk(a,out,0);return out;}private void walk(Object v,Map<String,Object> out,int depth){if(v==null||depth>3)return;if(v instanceof Map<?,?> m){m.forEach((k,x)->out.put(String.valueOf(k),x));return;}Class<?> c=v.getClass();if(c.isPrimitive()||v instanceof String||v instanceof Number||v instanceof Boolean)return;for(Method m:c.getMethods())try{if(m.getParameterCount()==0&&(m.getName().startsWith("get")||m.getName().startsWith("is"))&&!m.getName().equals("getClass")){Object x=m.invoke(v);String n=m.getName().replaceFirst("^(get|is)","");n=Character.toLowerCase(n.charAt(0))+n.substring(1);if(x==null)continue;if(x instanceof String||x instanceof Number||x instanceof Boolean||x instanceof Enum<?>)out.putIfAbsent(n,x);else walk(x,out,depth+1);}}catch(Exception ignored){}}
private Object adapt(Type generic,Class<?> raw,CleanPayClient.GatewayResponse r){if(raw==void.class)return null;if(raw==String.class)return r.transactionId();if(Map.class.isAssignableFrom(raw))return r.raw();if(raw==boolean.class||raw==Boolean.class)return r.approved();if(CompletionStage.class.isAssignableFrom(raw)||CompletableFuture.class.isAssignableFrom(raw)){Type inner=generic instanceof ParameterizedType p?p.getActualTypeArguments()[0]:Object.class;Class<?> ic=inner instanceof Class<?> c?c:Object.class;return CompletableFuture.completedFuture(adapt(inner,ic,r));}if(raw.getName().equals("reactor.core.publisher.Mono"))try{Type inner=generic instanceof ParameterizedType p?p.getActualTypeArguments()[0]:Object.class;Class<?> ic=inner instanceof Class<?> c?c:Object.class;return raw.getMethod("just",Object.class).invoke(null,adapt(inner,ic,r));}catch(Exception e){return null;}if(raw.isRecord())try{RecordComponent[] cs=raw.getRecordComponents();Object[] values=new Object[cs.length];Class<?>[] types=new Class<?>[cs.length];for(int i=0;i<cs.length;i++){types[i]=cs[i].getType();values[i]=value(cs[i].getName(),types[i],r);}return raw.getDeclaredConstructor(types).newInstance(values);}catch(Exception ignored){}for(Method m:raw.getMethods())if(Modifier.isStatic(m.getModifiers())&&List.of("success","approved","pending","requiresAction","failure","failed").contains(m.getName()))try{Object[] vals=new Object[m.getParameterCount()];Class<?>[] ts=m.getParameterTypes();for(int i=0;i<ts.length;i++)vals[i]=value("",ts[i],r);if((r.approved()&&m.getName().matches("success|approved"))||(r.requiresAction()&&m.getName().matches("pending|requiresAction"))||(!r.approved()&&!r.requiresAction()&&m.getName().matches("failure|failed")))return m.invoke(null,vals);}catch(Exception ignored){}try{Object o=raw.getDeclaredConstructor().newInstance();for(Method m:raw.getMethods())if(m.getName().startsWith("set")&&m.getParameterCount()==1)try{m.invoke(o,value(m.getName().substring(3),m.getParameterTypes()[0],r));}catch(Exception ignored){}return o;}catch(Exception ignored){return null;}}
private Object value(String name,Class<?> type,CleanPayClient.GatewayResponse r){String n=name.toLowerCase();if(type==String.class){if(n.contains("redirect")||n.contains("url"))return r.redirectUrl();if(n.contains("html")||n.contains("challenge"))return r.challengeHtml();if(n.contains("message")||n.contains("error"))return r.message();if(n.contains("status"))return r.status();return r.transactionId();}if(type==boolean.class||type==Boolean.class)return n.contains("action")||n.contains("3ds")?r.requiresAction():r.approved();if(type==URI.class&&r.redirectUrl()!=null)return URI.create(r.redirectUrl());if(Map.class.isAssignableFrom(type))return r.raw();if(type.isEnum()){String target=r.requiresAction()?"REQUIRES_ACTION":r.approved()?"APPROVED":"FAILED";for(Object e:type.getEnumConstants())if(String.valueOf(e).equalsIgnoreCase(target)||String.valueOf(e).toLowerCase().contains(target.toLowerCase().split("_")[0]))return e;return type.getEnumConstants().length>0?type.getEnumConstants()[0]:null;}if(type==int.class||type==Integer.class)return 0;if(type==long.class||type==Long.class)return 0L;return null;}
}
